UPDATE truss.feed_member m SET delivery_ordinal = $5::bigint WHERE m.source_epoch = $1::pg_catalog.text AND m.feed_profile = $2::pg_catalog.text AND m.original_writer_xid = pg_catalog.pg_current_xact_id_if_assigned() AND m.registration_address = $4::bigint AND m.delivery_ordinal IS NULL AND $4::bigint > 0 AND $5::bigint >= 0 AND EXISTS (SELECT 1 FROM truss.feed_tx t WHERE t.source_epoch = m.source_epoch AND t.feed_profile = m.feed_profile AND t.original_writer_xid = m.original_writer_xid AND t.membership_generation = $3::bigint AND t.finalized_generation IS NULL AND t.manifest_bytes IS NULL AND t.manifest_sha256 IS NULL) RETURNING m.source_epoch, m.feed_profile, m.original_writer_xid::pg_catalog.text AS original_writer_xid, m.registration_address::pg_catalog.text AS registration_address, m.delivery_ordinal::pg_catalog.text AS delivery_ordinal